    // evaluating it. A render-time fallback may already exist in memory, but it
    // must never mask a later IndexedDB read after a reload or authority gate.
    await hydrateFleetCommandDurables8622();
    const settlement8657=await settleProofChain8657(`readiness:${source}`);
    const barrierProof8611=settlement8657?.proof||await awaitProofBarrier8611({source:`readiness:${source}`,timeoutMs:700});
    const currentProof8611=(barrierProof8611?.ok?barrierProof8611:proofBarrierRead8611()?.currentProof)||null;
    const proofBlockedRoot8657=String(settlement8657?.root||'proof settlement incomplete');
    const checks=[];
    const add=(id,label,state,detail,level='core')=>checks.push({id,label,state,detail,level});
    const safe=async(fn,fallback)=>{try{return await fn();}catch(err){return fallback(err);}};
    const doctrine=persistAdmiralReleaseDoctrine();
    const doctrinePreflight=admiralDoctrinePreflight();
    add('admiral-doctrine','Admiral Release Doctrine registry',doctrine?.doctrineVersion===2?'pass':'fail',doctrine?.doctrineVersion===2?`${doctrine.principles.length} fleet principles and ${doctrine.learned.length} learned lessons retained for build ${BUILD_VERSION}.`:'Admiral release doctrine registry could not be retained.');
    add('detector-independence','Ike detector independence',doctrinePreflight.detectorIndependence?'pass':'fail',doctrinePreflight.detectorIndependence?'Proven orientation/species detectors are isolated from the experimental length pipeline.':'Experimental length segmentation can still suppress proven visual detectors.');
    const calibrationReplay=await admiralReplayKnownCalibrations();
    const calibrationIncident=admiralDiagnoseCalibrationReplay(calibrationReplay);
    add('known-calibration-replay','Known Ike calibration replay',calibrationReplay.protectedPass?(calibrationReplay.lengthWatch?'warn':'pass'):'fail',calibrationReplay.protectedPass?(calibrationReplay.lengthWatch?'Protected Horizontal + Cedar cases replayed cleanly; length remains experimental and retained as WATCH evidence.':'Known 2 ft Cedar calibration replay cleared protected and experimental expectations.'):`${calibrationIncident?.title||'Protected calibration replay failed'}. ${calibrationIncident?.recommendation||''}`);
    const lastRecovery=admiralLastRecovery();
    add('release-recovery-history','Last release recovery','pass',lastRecovery?.ok===true?`${lastRecovery.automatic?'Automatic safe recovery':'Clean recovery'} completed ${new Date(lastRecovery.at).toLocaleString()} for build ${lastRecovery.build}; project data remained untouched.`:'No retained clean-release recovery is required for this candidate.','check');
    const fleetLearning=persistFleetLearningRegistry();
    const learningRecommendations=fleetLearning.recommendations||[];
    const dangerousAutoApply=learningRecommendations.some(r=>r.status==='adopted'&&r.risk==='critical'&&r.class!=='doctrine');
    add('fleet-learning-registry','Fleet Learning Registry',dangerousAutoApply?'fail':'pass',dangerousAutoApply?'A critical reusable capability was adopted without a doctrine-only boundary.':`${FLEET_LEARNING_REGISTRY.filter(x=>x.class==='doctrine').length} fleet doctrines inherited automatically; ${fleetLearning.compressedDecisions?.length||0} compressed capability decision(s) remain; adoption stays explicit and project-scoped.`);

    // Authority contracts: read-only verification only; no failure counters are incremented.
    const engine=await safe(()=>verifyEnginePin(DEFAULT_ENGINE_PIN,{recordFailure:false}),()=>({ok:false}));
    add('engine-auth','Black Flag recovery access',engine?.ok===true?'pass':'fail',engine?.ok?'5615 recovery path verified without changing session state.':'Black Flag 5615 recovery path did not verify.');

    const readinessRows8611=currentProof8611?.ok===true?projects():await safe(()=>readCanonicalProjectRegistry(),()=>projects());
    const adminRows=[];
    for(const p of readinessRows8611){
      const result=await safe(()=>verifyProjectAdminPin(DEFAULT_ADMIN_PIN,p.id,{recordFailure:false}),()=>({ok:false}));
      adminRows.push({id:p.id,name:p.name,ok:result?.ok===true});
    }
    const adminBad=adminRows.filter(x=>!x.ok);
    add('project-admin','Project Admin fleet recovery',adminBad.length?'fail':'pass',adminBad.length?`${adminBad.length} project(s) rejected 4353: ${adminBad.map(x=>x.name).join(', ')}`:`4353 verified across ${adminRows.length} project(s).`);

    const captainPin=String(window.DarkSkyCaptainAuthContract?.pin||window.DarkSkyCaptainAuthContract?.recoveryPin||'');
    add('captain-auth','Captain authority boundary',captainPin==='19613'?'pass':'warn',captainPin==='19613'?'19613 Captain credential contract is published by the Captain module.':'Captain module did not publish its credential contract for runtime verification.');

    const ownerRows=readinessRows8611.map(p=>{ensureProjectGovernance(p);const inv=p.ownerAccess?.invitation;return {id:p.id,namespace:p.namespace||window.BlackFlagV3Core?.namespaceFor?.(p.id)||'',enabled:p.ownerAccess?.enabled!==false,invitationProject:inv?.projectId||p.id,invitationNamespace:inv?.namespace||''};});
