  function renderFlowersReview(){const box=$('flowersReviewSummary');if(!box)return;const clean=syncFlowersMessage({trim:true}),style=flowersState.style||'script',size=flowersPreviewFontPx(clean,style);box.innerHTML=`<div class="mugs-review-preview flowers-review-preview"><img src="${flowersState.photoData}" alt="Confirmed flower arrangement photo"><div class="mugs-review-overlay flowers-review-overlay mugs-style-${escapeHtml(style)}" style="--flowers-preview-size:${size}px">${escapeHtml(clean||'Your Message')}</div></div><div class="mugs-review-row"><span>Message</span><strong>${escapeHtml(clean)}</strong></div><div class="mugs-review-row"><span>Letter style</span><strong>${escapeHtml(style)}</strong></div><div class="mugs-review-row"><span>Name</span><strong>${escapeHtml(flowersState.customerName||'')}</strong></div><div class="mugs-review-row"><span>Phone</span><strong>${escapeHtml(flowersState.customerPhone||'')}</strong></div><div class="mugs-review-row"><span>Email</span><strong>${escapeHtml(flowersState.customerEmail||'')}</strong></div><div class="mugs-review-row"><span>Pricing</span><strong>TEST MODE</strong></div>`;}
  function wrapFlowersCanvasLines(ctx,text,maxWidth){const clean=normalizeFlowersMessage(text);if(!clean)return [''];const lines=[];clean.split('\n').forEach(paragraph=>{if(!paragraph){lines.push('');return;}let line='';for(const word of paragraph.split(/\s+/)){const trial=line?`${line} ${word}`:word;if(ctx.measureText(trial).width<=maxWidth){line=trial;continue;}if(line)lines.push(line);if(ctx.measureText(word).width<=maxWidth){line=word;continue;}let chunk='';for(const ch of Array.from(word)){const next=chunk+ch;if(chunk&&ctx.measureText(next).width>maxWidth){lines.push(chunk);chunk=ch;}else chunk=next;}line=chunk;}if(line)lines.push(line);});return lines.length?lines:[''];}
  function flowersCanvasRoundedRect(ctx,x,y,w,h,r){const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.lineTo(x+w-rr,y);ctx.quadraticCurveTo(x+w,y,x+w,y+rr);ctx.lineTo(x+w,y+h-rr);ctx.quadraticCurveTo(x+w,y+h,x+w-rr,y+h);ctx.lineTo(x+rr,y+h);ctx.quadraticCurveTo(x,y+h,x,y+h-rr);ctx.lineTo(x,y+rr);ctx.quadraticCurveTo(x,y,x+rr,y);ctx.closePath();}
  async function createFlowersApprovedPreview(){if(!flowersState.photoData)return '';return new Promise(resolve=>{const img=new Image();img.onload=()=>{try{const scale=Math.min(1,1600/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height)),w=Math.max(1,Math.round((img.naturalWidth||img.width)*scale)),h=Math.max(1,Math.round((img.naturalHeight||img.height)*scale)),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)return resolve('');ctx.drawImage(img,0,0,w,h);const text=normalizeFlowersMessage(flowersState.message)||'Your Message',style=flowersState.style||'script',family=style==='classic'?'Georgia':style==='script'?'cursive':'Arial',weight=style==='script'?600:style==='classic'?700:800,panelWidth=w*.78,pad=Math.max(18,Math.round(w*.025)),maxTextWidth=panelWidth-pad*2;let size=Math.max(20,Math.min(Math.round(w*.044),48)),lines=[],lineHeight=0,panelHeight=0;while(size>=18){ctx.font=`${weight} ${size}px ${family}`;lines=wrapFlowersCanvasLines(ctx,text,maxTextWidth);lineHeight=size*1.18;panelHeight=lines.length*lineHeight+pad*1.8;if(lines.length<=5&&panelHeight<=h*.42)break;size-=2;}const x=(w-panelWidth)/2,y=h-panelHeight-Math.max(18,h*.035);flowersCanvasRoundedRect(ctx,x,y,panelWidth,panelHeight,Math.max(16,w*.018));ctx.fillStyle='rgba(255,250,244,.94)';ctx.fill();ctx.lineWidth=Math.max(1.5,w*.0016);ctx.strokeStyle='rgba(180,130,145,.55)';ctx.stroke();ctx.font=`${weight} ${size}px ${family}`;ctx.fillStyle='#24372b';ctx.textAlign='center';ctx.textBaseline='middle';const startY=y+panelHeight/2-((lines.length-1)*lineHeight/2);lines.forEach((line,i)=>ctx.fillText(line,w/2,startY+i*lineHeight,maxTextWidth));resolve(canvas.toDataURL('image/jpeg',.86));}catch(err){console.warn('Flowers preview failed',err);resolve('');}};img.onerror=()=>resolve('');img.src=flowersState.photoData;});}
  async function submitFlowersOrder(){
    const p=projectById(activeProjectId);
    if(!p || projectShellFor(p)!=='flowers'){
      alert('This flower order is not attached to an active flower project. Return to Black Flag and reopen the project.');
      return;
    }
    if(!flowersState.photoData){alert('A confirmed flower arrangement photo is required.');showFlowersScreen('photo');return;}
    const cleanMessage=syncFlowersMessage({trim:true});
    if(!cleanMessage){alert('Enter the card message.');showFlowersScreen('message');return;}
    if(!flowersState.customerName.trim()||!flowersState.customerPhone.trim()||!flowersState.customerEmail.trim()){alert('Name, phone, and email are required.');showFlowersScreen('customer');return;}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(flowersState.customerEmail.trim())){alert('Enter a valid email address.');showFlowersScreen('customer');return;}
    if(!$('flowersApprovalCheck')?.checked)return;

    const approvedPreviewData=await createFlowersApprovedPreview();
    if(!approvedPreviewData){alert('The approved flower preview could not be confirmed.');showFlowersScreen('photo');return;}

    const prefix=String(p.orderPrefix||'FLW').toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,8)||'FLW';
    const businessName=p?.branding?.businessName||p.name||'Flower Project';
    const d=new Date(),y=String(d.getFullYear()).slice(-2),mo=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');
    const suffix=(Date.now().toString(36).slice(-4)+Math.random().toString(36).slice(2,4)).toUpperCase();
    const id=`${prefix}-${y}${mo}${day}-${suffix}`;

    const order={
      projectId:p.id,
      namespace:window.BlackFlagV3Core?.namespaceFor?.(p.id)||`bf.project.${p.id}`,
      isolation:{projectId:p.id,crossProjectAccess:'deny'},
      schemaVersion:Number(engineConfig.schemaVersion||3),
      business:{name:businessName,orderPrefix:prefix},
      id,
      createdAt:new Date().toISOString(),
      updatedAt:new Date().toISOString(),
      status:'New',
      price:0,
      photoData:flowersState.photoData,
      approvedPreviewData,
      wording:cleanMessage,
      font:flowersState.style,
      fill:'Black',
      contactPreference:'Text',
      customerName:flowersState.customerName,
      customerPhone:flowersState.customerPhone,
      customerEmail:flowersState.customerEmail,
      approved:true,
      testMode:currentExperienceContext(p)?.state!=='deployed',
      deploymentId:currentExperienceContext(p)?.deploymentId||null
    };

    const flowersCtx=currentExperienceContext(p);
    if(flowersCtx?.state==='deployed'){
      alert('Production flower-photo custody is not configured yet. Black Flag will not store this customer photo in browser order storage. Keep this vessel in testing until private production media storage is commissioned.');
      return;
    }
    if(flowersCtx?.state==='sea_trial'){
      const storedOrder=flowerOrderStorageRecord(order);
      backupOrderLocally(storedOrder);
      try{await put(STORE_ORDERS,storedOrder);}catch(err){console.warn('Flowers test order save failed',err);alert(`The ${activityTermsForProject(p).lowerSingular} test record could not be saved. Please try again.`);return;}
      await recordExperienceSeaTrialSubmission(p,id);
    }

    flowersState.approvedPreviewData=approvedPreviewData;
    if($('flowersDoneOrderId'))$('flowersDoneOrderId').textContent=id;
    if($('flowersDonePreview'))$('flowersDonePreview').src=approvedPreviewData;
    showFlowersScreen('done');
  }

